function App() {
  const answers = {
    'CSS reset + design tokens': 'Global CSS — applies app-wide, ideal for variables/resets',
    'Component-scoped plain CSS': 'CSS Modules — hashed class names, no collisions',
    'Fast utility-driven styling': 'Tailwind — build-time static CSS, tree-shaken, no runtime JS',
    'Self-host fonts, no layout shift': 'next/font — self-hosts, removes blocking requests, prevents CLS',
  };
  return (
    <ul style={{ fontFamily: 'system-ui', padding: 16 }}>
      {Object.entries(answers).map(([k, v]) => <li key={k}><b>{k}:</b> {v}</li>)}
    </ul>
  );
}
